def transform(grid):
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0
    result = [row[:] for row in grid]

    for c in range(width):
        top_row = -1
        top_val = None
        for r in range(height):
            if grid[r][c] != 0:
                top_row = r
                top_val = grid[r][c]
                break

        bottom_row = -1
        bottom_val = None
        for r in range(height - 1, -1, -1):
            if grid[r][c] != 0:
                bottom_row = r
                bottom_val = grid[r][c]
                break

        if top_val is not None and bottom_val is not None and top_val == bottom_val:
            fill_val = top_val + 1
            r = top_row + 1
            while r < height:
                if result[r][c] != 0:
                    break
                result[r][c] = fill_val
                r += 1

    return result

